#!/usr/bin/env python3
"""tmpreaper.py - safely reap old temp files.

Safety rails:
  * never follows symlinks (symlinks are ignored, their targets untouched)
  * refuses to operate on / or $HOME directly
  * --dry-run prints a full deletion plan without touching anything
"""

from __future__ import annotations

import argparse
import fnmatch
import os
import sys
import time
from dataclasses import dataclass
from pathlib import Path
from typing import Iterable, List, Optional, Sequence

DURATION_UNITS = {
    "s": 1,
    "m": 60,
    "h": 3600,
    "d": 86400,
    "w": 604800,
}


class SafetyError(SystemExit):
    """Refusal to run; exits with status 2."""


def parse_duration(spec: str) -> int:
    """Parse '7d', '12h', '30m', '90s', '2w' into seconds."""
    spec = spec.strip().lower()
    if len(spec) < 2 or not spec[:-1].isdigit() or spec[-1] not in DURATION_UNITS:
        raise argparse.ArgumentTypeError(
            f"invalid duration {spec!r} (expected e.g. 30s, 10m, 12h, 7d, 2w)"
        )
    return int(spec[:-1]) * DURATION_UNITS[spec[-1]]


def parse_size(spec: str) -> int:
    """Parse '10MB', '512KB', '1GB', '4096' into bytes."""
    spec = spec.strip().upper()
    units = {"B": 1, "KB": 1024, "MB": 1024**2, "GB": 1024**3}
    for suffix, mult in sorted(units.items(), key=lambda kv: -len(kv[0])):
        if spec.endswith(suffix):
            num = spec[: -len(suffix)].strip()
            if not num.replace(".", "", 1).isdigit():
                break
            return int(float(num) * mult)
    raise argparse.ArgumentTypeError(f"invalid size {spec!r} (expected e.g. 512KB, 10MB, 1GB)")


@dataclass
class Victim:
    """A file selected for deletion."""

    path: Path
    size: int
    mtime: float

    @property
    def age(self) -> float:
        raise NotImplementedError  # computed against injected now; see plan()


def _human(nbytes: float) -> str:
    for unit in ("B", "KB", "MB", "GB"):
        if nbytes < 1024 or unit == "GB":
            return f"{nbytes:.1f}{unit}" if unit != "B" else f"{int(nbytes)}B"
        nbytes /= 1024
    return f"{nbytes:.1f}GB"


def _human_age(seconds: float) -> str:
    seconds = int(seconds)
    d, rem = divmod(seconds, 86400)
    h, rem = divmod(rem, 3600)
    m, s = divmod(rem, 60)
    parts = []
    if d:
        parts.append(f"{d}d")
    if h:
        parts.append(f"{h}h")
    if m:
        parts.append(f"{m}m")
    parts.append(f"{s}s")
    return "".join(parts)


def _matches(path: Path, patterns: Sequence[str]) -> bool:
    name = path.name
    return any(fnmatch.fnmatch(name, pat) for pat in patterns)


def collect_candidates(
    root: Path,
    patterns: Sequence[str],
    now: Optional[float] = None,
) -> List[Victim]:
    """All regular files under root matching any pattern. Symlinks ignored."""
    now = time.time() if now is None else now
    candidates: List[Victim] = []
    # walk without following symlinks anywhere
    for dirpath, dirnames, filenames in os.walk(root, followlinks=False):
        dirnames[:] = [
            d for d in dirnames if not os.path.islink(os.path.join(dirpath, d))
        ]
        for fname in filenames:
            full = Path(dirpath) / fname
            if full.is_symlink():  # never touch symlinks themselves
                continue
            try:
                st = full.stat()  # stat follows nothing here: not a symlink
            except OSError:
                continue
            if not _matches(full, patterns):
                continue
            candidates.append(Victim(path=full, size=st.st_size, mtime=st.st_mtime))
    return candidates


def build_plan(
    root: Path,
    patterns: Sequence[str],
    older_than: int,
    max_total_size: Optional[int] = None,
    now: Optional[float] = None,
) -> List[Victim]:
    """Files to delete: old enough, then oldest-first until under the size cap."""
    now = time.time() if now is None else now
    old_enough = [v for v in collect_candidates(root, patterns, now=now)
                  if now - v.mtime >= older_than]
    if max_total_size is None:
        return old_enough

    total = sum(v.size for v in old_enough)
    if total <= max_total_size:
        return []
    # delete oldest first until the *remaining* matching set fits under the cap
    to_delete: List[Victim] = []
    for victim in sorted(old_enough, key=lambda v: v.mtime):
        if total <= max_total_size:
            break
        to_delete.append(victim)
        total -= victim.size
    return to_delete


def check_safety(root: Path) -> None:
    """Refuse to run on / or $HOME."""
    resolved = root.expanduser().resolve()
    home = Path.home().resolve()
    if resolved == Path(resolved.anchor):
        raise SafetyError("refusing to run on filesystem root /")
    if resolved == home:
        raise SafetyError(f"refusing to run on home directory {home}")
    if resolved == home.parent and home.name in ("", home.name):
        pass  # parent of home is fine


def format_plan(
    plan: List[Victim],
    now: Optional[float] = None,
    root: Optional[Path] = None,
) -> str:
    now = time.time() if now is None else now
    lines: List[str] = []
    header = "DRY RUN - deletion plan" if root is None else f"Deletion plan for {root}"
    lines.append(header)
    lines.append("-" * 72)
    for v in sorted(plan, key=lambda x: x.mtime):
        lines.append(
            f"DELETE {_human(v.size):>9}  age={_human_age(now - v.mtime):>9}  {v.path}"
        )
    lines.append("-" * 72)
    total_size = sum(v.size for v in plan)
    lines.append(f"total: {len(plan)} file(s), {_human(total_size)}")
    return "\n".join(lines)


def execute(plan: List[Victim]) -> int:
    deleted = 0
    for v in plan:
        try:
            v.path.unlink()
            deleted += 1
        except OSError as exc:
            print(f"warning: could not delete {v.path}: {exc}", file=sys.stderr)
    return deleted


def main(argv: Optional[Sequence[str]] = None) -> int:
    parser = argparse.ArgumentParser(
        prog="tmpreaper",
        description="Delete old temp files matching glob patterns, safely.",
    )
    parser.add_argument("root", type=Path, help="directory to clean")
    parser.add_argument(
        "--older-than", type=parse_duration, default="7d", metavar="DUR",
        help="only touch files older than this (e.g. 30s, 10m, 12h, 7d); default 7d",
    )
    parser.add_argument(
        "--pattern", action="append", default=["*.tmp"], metavar="GLOB",
        help="glob pattern(s), repeatable; default *.tmp",
    )
    parser.add_argument(
        "--max-total-size", type=parse_size, default=None, metavar="SIZE",
        help="delete oldest matching files until matching set is under SIZE (e.g. 10MB)",
    )
    parser.add_argument("--dry-run", action="store_true", help="print plan, delete nothing")
    args = parser.parse_args(argv)

    try:
        check_safety(args.root)
    except SafetyError as exc:
        print(f"error: {exc}", file=sys.stderr)
        raise SystemExit(2)

    plan = build_plan(
        args.root.resolve(),
        args.pattern,
        args.older_than,
        args.max_total_size,
    )

    if args.dry_run:
        print(format_plan(plan, root=args.root))
        print("(dry run: nothing deleted)")
        return 0

    n = execute(plan)
    freed = sum(v.size for v in plan)
    print(f"deleted {n} file(s), freed {_human(freed)} from {args.root}")
    return 0


if __name__ == "__main__":
    sys.exit(main())

