    units = {"B": 1, "KB": 1024, "MB": 1024**2, "GB": 1024**3}
    for suffix, mult in sorted(units.items(), key=lambda kv: -len(kv[0])):
        if spec.endswith(suffix):
            num = spec[: -len(suffix)].strip()
            if num.replace(".", "", 1).isdigit():
                return int(float(num) * mult)
    raise argparse.ArgumentTypeError(f"invalid size {spec!r} (expected e.g. 512KB, 10MB, 1GB)")


@dataclass
class Victim:
    """A file selected for deletion."""

    path: Path
    size: int
    mtime: float

    def age(self, now: Optional[float] = None) -> float:
        return (time.time() if now is None else now) - self.mtime


def _human(nbytes: float) -> str:
    for unit in ("B", "KB", "MB", "GB"):
        if nbytes < 1024 or unit == "GB":
            return f"{nbytes:.1f}{unit}" if unit != "B" else f"{int(nbytes)}B"
        nbytes /= 1024
    return f"{nbytes:.1f}GB"


def _human_age(seconds: float) -> str:
    seconds = int(seconds)
    d, rem = divmod(seconds, 86400)
    h, rem = divmod(rem, 3600)
    m, s = divmod(rem, 60)
    parts = []
    if d:
        parts.append(f"{d}d")
    if h:
        parts.append(f"{h}h")
    if m:
        parts.append(f"{m}m")
    parts.append(f"{s}s")
    return "".join(parts)


def _matches(path: Path, patterns: Sequence[str]) -> bool:
    return any(fnmatch.fnmatch(path.name, pat) for pat in patterns)


def collect_candidates(
    root: Path,
    patterns: Sequence[str],
    now: Optional[float] = None,
) -> List[Victim]:
    """All regular files under root matching any pattern. Symlinks never followed."""
    candidates: List[Victim] = []
    for dirpath, dirnames, filenames in os.walk(root, followlinks=False):
        # prune symlinked directories so we never descend through them
        dirnames[:] = [
            d for d in dirnames
            if not os.path.islink(os.path.join(dirpath, d))
        ]
        for fname in filenames:
            full = Path(dirpath) / fname
            if full.is_symlink():  # never delete symlinks themselves either
                continue
            try:
                st = full.stat()
            except OSError:
                continue
            if not _matches(full, patterns):
                continue
            candidates.append(Victim(path=full, size=st.st_size, mtime=st.st_mtime))
    return candidates


def build_plan(
    root: Path,
    patterns: Sequence[str],
    older_than: int,
    max_total_size: Optional[int] = None,
    now: Optional[float] = None,
) -> List[Victim]:
    """Files to delete: old enough, then oldest-first until the set is under the cap."""
    now = time.time() if now is None else now
    old_enough = [
        v for v in collect_candidates(root, patterns, now=now)
        if now - v.mtime >= older_than
    ]
    if max_total_size is None:
        return old_enough

    total = sum(v.size for v in old_enough)
    if total <= max_total_size:
        return []
    to_delete: List[Victim] = []
    for victim in sorted(old_enough, key=lambda v: v.mtime):
        if total <= max_total_size:
            break
        to_delete.append(victim)
        total -= victim.size
    return to_delete


def check_safety(root: Path) -> None:
    """Refuse to run on / or $HOME."""
    resolved = root.expanduser().resolve()
    if resolved == Path(resolved.anchor):
        raise SafetyError("refusing to run on filesystem root /")
    if resolved == Path.home().resolve():
        home = Path.home().resolve()
        raise SafetyError(f"refusing to run on home directory {home}")


def format_plan(
    plan: List[Victim],
    now: Optional[float] = None,
    root: Optional[Path] = None,
) -> str:
    now = time.time() if now is None else now
    lines = [f"Deletion plan for {root}" if root else "Deletion plan", "-" * 72]
    for v in sorted(plan, key=lambda x: x.mtime):
        lines.append(
            f"DELETE {_human(v.size):>9}  age={_human_age(v.age(now)):>9}  {v.path}"
        )
    lines.append("-" * 72)
    lines.append(f"total: {len(plan)} file(s), {_human(sum(v.size for v in plan))}")
    return "\n".join(lines)


def execute(plan: List[Victim]) -> int:
    deleted = 0
    for v in plan:
        try:
            v.path.unlink()
            deleted += 1
        except OSError as exc:
            print(f"warning: could not delete {v.path}: {exc}", file=sys.stderr)
    return deleted


def main(argv: Optional[Sequence[str]] = None) -> int:
    parser = argparse.ArgumentParser(
        prog="tmpreaper",
        description="Delete old temp files matching glob patterns, safely.",
    )
    parser.add_argument("root", type=Path, help="directory to clean")
    parser.add_argument(
        "--older-than", type=parse_duration, default="7d", metavar="DUR",
        help="only touch files older than this (e.g. 30s, 10m, 12h, 7d); default 7d",
    )
    parser.add_argument(
        "--pattern", action="append", default=["*.tmp"], metavar="GLOB",
        help="glob pattern(s), repeatable; default *.tmp",
    )
    parser.add_argument(
        "--max-total-size", type=parse_size, default=None, metavar="SIZE",
        help="delete oldest matching files until matching set is under SIZE (e.g. 10MB)",
    )
    parser.add_argument("--dry-run", action="store_true", help="print plan, delete nothing")
    args = parser.parse_args(argv)

    try:
        check_safety(args.root)
    except SafetyError as exc:
        print(f"error: {exc}", file=sys.stderr)
        raise SystemExit(2)

    plan = build_plan(args.root.resolve(), args.pattern, args.older_than, args.max_total_size)

    if args.dry_run:
        print(format_plan(plan, root=args.root))
        print("(dry run: nothing deleted)")
        return 0

    n = execute(plan)
    print(f"deleted {n} file(s), freed {_human(sum(v.size for v in plan))} from {args.root}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
